import assert from 'node:assert/strict';

const literalEscapes: Readonly<Record<string, string>> = {
  '<': '\\u003c',
  '>': '\\u003e',
  '\b': '\\b',
  '\f': '\\f',
  '\n': '\\n',
  '\r': '\\r',
  '\t': '\\t',
  '\0': '\\u0000',
  '\u2028': '\\u2028',
  '\u2029': '\\u2029',
};
/** Serialize data embedded in TEST CDP JavaScript; never concatenate it as source. */
export function desktopJsLiteral(value: unknown): string {
  const serialized = JSON.stringify(value);
  if (typeof serialized !== 'string') throw new TypeError('TEST CDP value is not JSON-serializable');
  return serialized.replace(/[<>\b\f\n\r\t\0\u2028\u2029]/g, (char) => literalEscapes[char]!);
}

export interface UiCdpPort {
  evaluate(expression: string): Promise<unknown>;
  send(method: string, params?: Record<string, unknown>): Promise<unknown>;
}
const record = (value: unknown): Record<string, unknown> => {
  assert.ok(value && typeof value === 'object' && !Array.isArray(value));
  return value as Record<string, unknown>;
};
/** Shared TEST renderer input/navigation. DOM evaluation never dispatches app actions. */
export function createDesktopUiControls(
  cdp: UiCdpPort,
  options: {
    assertOwnedRenderer(): void;
    step(value: Record<string, unknown>): void;
  }
) {
  const step = options.step;
  const observeInput = async (): Promise<void> => {
    // macOS occlusion can leave this TEST Electron page hidden after reload.
    // Chromium then acknowledges Input commands without delivering DOM events.
    // Focus emulation is confined to this captured TEST renderer, never app state.
    await cdp.send('Emulation.setFocusEmulationEnabled', { enabled: true });
    // TEST-only passive observation; handlers never prevent, dispatch or mutate app state.
    await cdp.evaluate(`(() => {
      window.__TEST_desktopInputEvents=[];
      window.__TEST_desktopDragEvents=[];
      const describe=el=>el instanceof Element?{tag:el.tagName,id:el.id,ariaLabel:el.getAttribute('aria-label'),className:String(el.className).slice(0,120)}:null;
      const teamNavigation=e=>{
        const own=(value,key)=>{if(!value||(typeof value!=='object'&&typeof value!=='function'))throw Error();const d=Object.getOwnPropertyDescriptor(value,key);if(!d||!('value'in d))throw Error();return d.value;};
        const id=value=>typeof value==='string'&&value.length>0&&value.length<=128&&!/[^A-Za-z0-9_.:-]/.test(value);
        const key=value=>{if(typeof value!=='string'||value.length>256||!value.startsWith('host-team:'))return false;const handle=decodeURIComponent(value.slice(10));return handle.length>0&&handle.length<=256&&!handle.includes('\\0')&&'host-team:'+encodeURIComponent(handle)===value;};
        const sample=()=>{
          try{
            const store=own(window,'__agentTeamsDevStore'),getState=own(store,'getState');if(typeof getState!=='function')throw Error();
            const state=getState.call(store),layout=own(state,'paneLayout'),focused=own(layout,'focusedPaneId'),panes=own(layout,'panes'),selected=own(state,'selectedTeamName');
            if(!id(focused)||!(selected===null||key(selected))||!Array.isArray(panes))throw Error();
            const paneCount=own(panes,'length');if(!Number.isSafeInteger(paneCount)||paneCount<1||paneCount>4)throw Error();
            const seen=new Set();let pane=null;
            for(let index=0;index<paneCount;index++){const item=own(panes,index),paneId=own(item,'id');if(!id(paneId)||seen.has(paneId))throw Error();seen.add(paneId);if(paneId===focused)pane=item;}
            if(!pane)throw Error();const active=own(pane,'activeTabId'),tabs=own(pane,'tabs');
            if(!(active===null||id(active))||!Array.isArray(tabs))throw Error();
            const tabCount=own(tabs,'length');if(!Number.isSafeInteger(tabCount)||tabCount<0||tabCount>128)throw Error();
            let tab=null,tabType=null,tabTeam=null;
            if(active!==null){
              for(let index=0;index<tabCount;index++){const item=own(tabs,index),tabId=own(item,'id');if(!id(tabId))throw Error();if(tabId===active){if(tab)throw Error();tab=item;}}
              if(!tab)throw Error();const type=own(tab,'type');if(typeof type!=='string'||!type)throw Error();tabType=type==='team'?'team':'other';
              if(tabType==='team'){tabTeam=own(tab,'teamName');if(!key(tabTeam))throw Error();}
            }
            return {status:'available',focusedPaneId:focused,activeTabId:active,activeTabType:tabType,activeTabTeamName:tabTeam,selectedTeamName:selected};
          }catch{return {status:'unavailable'};}
        };
        let target=null;
        try{const card=e.target instanceof Element?e.target.closest('[data-team-name]'):null;if(card&&card.matches('.team-row-zebra-card')){const name=card.getAttribute('data-team-name');target=key(name)?name:undefined;}}catch{target=undefined;}
        let observation=target===null?null:typeof target==='string'?{schemaVersion:1,status:'available',source:'original-passive-input',atomicWithNavigation:false,targetTeamName:target,before:null,microtask:null,afterDispatch:null}:{schemaVersion:1,status:'unavailable',reason:'target'};
        return (row,phase)=>{
          try{
            if(observation?.status==='available')observation=Object.freeze({...observation,[phase]:Object.freeze(sample())});
            row.teamNavigation=JSON.stringify(observation).length<=4096?observation:{schemaVersion:1,status:'unavailable',reason:'projection-limit'};
          }catch{}
        };
      };
      const taskClarification=e=>{
        try{
          const target=e.target instanceof Element?e.target:null,dialog=target?.closest('[role="dialog"]');
          if(!dialog||!dialog.getClientRects().length)return null;
          const buttons=dialog.querySelectorAll('button');if(buttons.length>128)return null;
          const matches=[...buttons].filter(button=>button.textContent?.trim()==='Mark resolved');
          if(matches.length!==1||!(matches[0] instanceof HTMLButtonElement))return null;
          const control=matches[0],rect=control.getBoundingClientRect();
          const point=Number.isFinite(e.clientX)&&Number.isFinite(e.clientY);
          const geometry=[rect.left,rect.right,rect.top,rect.bottom,rect.width,rect.height].every(Number.isFinite);
          const hit=point?document.elementFromPoint(e.clientX,e.clientY):null;
          const pointer=getComputedStyle(control).pointerEvents;
          const facts={
            targetIsControl:target===control||control.contains(target),
            targetIsControlParent:target===control.parentElement,
            pointInsideControl:point&&geometry?rect.width>0&&rect.height>0&&e.clientX>=rect.left&&e.clientX<rect.right&&e.clientY>=rect.top&&e.clientY<rect.bottom:null,
            pointHitsControl:point?hit===control||control.contains(hit):null,
            controlConnected:control.isConnected,controlDisabled:control.disabled,
            pointerEvents:pointer==='auto'||pointer==='none'?pointer:typeof pointer==='string'&&pointer?'other':null,
            renderedOwner:null,storedSurfaceMatches:null,storedRevisionMatches:null,
            contextMatches:null,selectedTeamMatches:null,detailPhase:null,
            detailLoading:null,detailRefreshPending:null,deletionIntentPresent:null
          };
          const finish=()=>JSON.stringify(facts).length<=768?facts:null;
          const own=(value,key)=>{
            if(!value||(typeof value!=='object'&&typeof value!=='function'))return undefined;
            const descriptor=Object.getOwnPropertyDescriptor(value,key);
            return descriptor&&'value' in descriptor?descriptor.value:undefined;
          };
          const text=value=>typeof value==='string'&&value.length>0;
          const bool=value=>typeof value==='boolean'?value:null;
          const currentFiber=node=>{
            const keys=Object.keys(node).filter(key=>key.startsWith('__reactFiber$'));
            if(keys.length!==1)return null;const fiber=own(node,keys[0]);
            for(const candidate of [fiber,own(fiber,'alternate')]){
              if(!candidate)continue;let root=candidate,depth=0;
              while(own(root,'return')&&depth++<256)root=own(root,'return');
              if(!own(root,'return')&&own(own(root,'stateNode'),'current')===root)return candidate;
            }
            return null;
          };
          const controllers=new Set();let ambiguous=false,fiber=currentFiber(dialog),depth=0;
          for(;fiber&&depth<128;fiber=own(fiber,'return'),depth++){
            const props=own(fiber,'memoizedProps'),controller=own(props,'sessionController');
            if(own(props,'open')!==true||controller===undefined)continue;
            const identity=own(controller,'identity'),team=own(props,'teamName'),task=own(own(props,'task'),'id');
            if(!text(team)||!text(task)||!text(own(identity,'contextId'))||
              own(identity,'teamName')!==team||own(identity,'taskId')!==task||!text(own(controller,'surfaceId'))){
              ambiguous=true;continue;
            }
            controllers.add(controller);
          }
          if(fiber||ambiguous||controllers.size!==1)return finish();
          const controller=[...controllers][0],identity=own(controller,'identity'),surface=own(controller,'surfaceId');
          facts.renderedOwner=bool(own(controller,'isOwner'));
          const getState=own(own(window,'__agentTeamsDevStore'),'getState');
          if(typeof getState!=='function')return finish();const state=getState();
          const context=own(identity,'contextId'),team=own(identity,'teamName'),task=own(identity,'taskId');
          const key=JSON.stringify([context,team,task]);
          const session=own(own(state,'taskDetailSessionById'),key),renderedSession=own(controller,'session');
          const storedSurface=own(session,'ownerSurfaceId');
          facts.storedSurfaceMatches=storedSurface===null||text(storedSurface)?storedSurface===surface:null;
          const storedRevision=own(session,'ownerRevision'),renderedRevision=own(renderedSession,'ownerRevision');
          facts.storedRevisionMatches=Number.isSafeInteger(storedRevision)&&storedRevision>=0&&Number.isSafeInteger(renderedRevision)&&renderedRevision>=0?storedRevision===renderedRevision:null;
          const activeContext=own(state,'activeContextId'),switching=own(state,'isContextSwitching'),selectedTeam=own(state,'selectedTeamName');
          facts.contextMatches=text(activeContext)&&typeof switching==='boolean'?!switching&&activeContext===context:null;
          facts.selectedTeamMatches=selectedTeam===null||text(selectedTeam)?selectedTeam===team:null;
          const detail=own(own(state,'taskDetailById'),key),detailIdentity=own(detail,'identity');
          if(own(detailIdentity,'contextId')===context&&own(detailIdentity,'teamName')===team&&own(detailIdentity,'taskId')===task){
            const phase=own(detail,'phase'),deletion=own(detail,'deletionIntent');
            facts.detailPhase=['hydrating','ready','missing','deleted','provisioning','unavailable'].includes(phase)?phase:null;
            facts.detailLoading=bool(own(detail,'loading'));facts.detailRefreshPending=bool(own(detail,'refreshPending'));
            facts.deletionIntentPresent=deletion===null?false:deletion==='deleting'||deletion==='restoring'?true:null;
          }
          return finish();
        }catch{return null;}
      };
      for(const type of ['pointerdown','pointerup','pointercancel','pointermove','click','keydown','keyup','focusin','focusout'])document.addEventListener(type,e=>{
        if(type==='pointermove'&&!e.buttons)return;
        const navigation=type==='pointerdown'||type==='pointerup'||type==='click'?teamNavigation(e):null;
        const dragging=type==='pointermove'||type==='pointercancel';
        const rows=dragging?window.__TEST_desktopDragEvents:window.__TEST_desktopInputEvents;if(rows.length>=(dragging?32:96))rows.shift();
        const el=e.target instanceof Element?e.target.closest('button'):null;
        const row={type,timeMs:Math.round(performance.now()),x:e.clientX,y:e.clientY,button:e.button,buttons:e.buttons,key:e.key,code:e.code,
          trusted:e.isTrusted,buttonClass:el?.className?.slice(0,120)??null,
          target:describe(e.target),focusBefore:describe(document.activeElement),defaultPreventedBefore:e.defaultPrevented,
          sidebarRow:Boolean(el?.classList.contains('sidebar-task-item')),
          taskId:e.target instanceof Element?e.target.closest('.kanban-task-card')?.getAttribute('data-task-id')??null:null,
          activeSortable:[...document.querySelectorAll('[aria-roledescription="sortable"][aria-pressed="true"]')].map(el=>({taskId:el.querySelector('.kanban-task-card')?.getAttribute('data-task-id'),transform:el.style.transform})),
          dragAnnouncement:[...document.querySelectorAll('[id^="DndLiveRegion-"]')].map(el=>el.textContent)};
        if(type==='pointerdown'||type==='pointerup'||type==='click')row.taskClarification=taskClarification(e);
        if(navigation)navigation(row,'before');
        rows.push(row);queueMicrotask(()=>{row.defaultPreventedAfterMicrotask=e.defaultPrevented;row.focusAfterMicrotask=describe(document.activeElement);
          if(navigation)navigation(row,'microtask');
          setTimeout(()=>{row.defaultPreventedAfterDispatch=e.defaultPrevented;row.focusAfterDispatch=describe(document.activeElement);if(navigation)navigation(row,'afterDispatch');},0);});
      },{capture:true,passive:true});return true;
    })()`);
    assert.equal(
      await cdp.evaluate('document.visibilityState'),
      'visible',
      'captured TEST renderer is visible before dispatching user input'
    );
  };
  const waitRead = async (
    expression: string,
    label: string,
    timeoutMs = 30_000,
    isReady: (value: unknown) => boolean = Boolean
  ): Promise<unknown> => {
    const deadline = Date.now() + timeoutMs;
    while (Date.now() < deadline) {
      options.assertOwnedRenderer();
      try {
        const value = await cdp.evaluate(expression);
        if (isReady(value)) return value;
      } catch (error) {
        if (
          !/execution context was destroyed|cannot find (?:default )?execution context|cannot find context with specified id/i.test(
            String(error)
          )
        )
          throw error;
      }
      await new Promise<void>((done) => setTimeout(done, 100));
    }
    throw new Error(`UI read timed out: ${label}; no mutation retry`);
  };
  // Each expression is a read-only DOM lookup returning at most one exact target.
  const target = (selector: string, text?: string): string => `(() => {
    const elements = [...document.querySelectorAll(${desktopJsLiteral(selector)})].filter(e => {
      const r=e.getBoundingClientRect(); return r.width>0&&r.height>0${text === undefined ? '' : `&&e.textContent.trim()===${desktopJsLiteral(text)}`};
    });
    if(elements.length!==1)return {unavailableTarget:true,matches:Math.min(elements.length,256)};
    const e=elements[0], r=e.getBoundingClientRect(), x=r.x+r.width/2,y=r.y+r.height/2;
    const hit=document.elementFromPoint(x,y), disabled=e.matches(':disabled');
    if(!hit||!(hit===e||e.contains(hit))||disabled)return {
      unavailableTarget:true,matches:1,disabled,ariaDisabled:e.getAttribute('aria-disabled')==='true',
      pointerEventsNone:getComputedStyle(e).pointerEvents==='none',
      centerInViewport:x>=0&&y>=0&&x<innerWidth&&y<innerHeight,hitPresent:Boolean(hit)
    };
    return {x,y,text:e.textContent.trim().slice(0,300),tag:e.tagName};
  })()`;
  const clickExpression = async (
    expression: string,
    label: string,
    selector?: string,
    text?: string
  ): Promise<void> => {
    await cdp.send('Page.bringToFront');
    // Reuse the original passive reads and deadline. Retain only closed facts,
    // never DOM text, attributes, HTML or another request after a failed click.
    const readPoint = async (phase: string): Promise<Record<string, unknown>> => {
      const bootstrapRead = phase === label && label === 'open existing More menu' &&
        selector === 'button[aria-label="More actions"]';
      const readExpression = bootstrapRead
        ? `(() => {
            const point = ${expression};
            if (!point || point.unavailableTarget !== true) return point;
            try {
              const root = document.getElementById('root'), splash = document.getElementById('splash');
              const bounds = splash?.getBoundingClientRect(), child = root?.firstElementChild;
              return { ...point, bootstrapFacts: {
                rawMatches: Math.min(document.querySelectorAll(${desktopJsLiteral(selector)}).length, 256),
                rootPresent: root !== null, rootChildren: Math.min(root?.childElementCount ?? 0, 16),
                uiInitialized: window.__claudeTeamsUiDidInit === true,
                splashPresent: splash !== null, splashPositiveSize: Boolean(bounds && bounds.width > 0 && bounds.height > 0),
                splashError: splash?.classList.contains('splash-status-error') === true,
                splashSlow: splash?.classList.contains('splash-status-slow') === true,
                documentComplete: document.readyState === 'complete',
                languageEnglish: document.documentElement.lang === 'en',
                languageEmpty: document.documentElement.lang === '',
                rootFallbackShape: Boolean(root?.childElementCount === 1 &&
                  child?.matches('div.flex.h-screen.flex-col.items-center.justify-center') &&
                  child.querySelector(':scope > div > h1.text-2xl.font-semibold') &&
                  child.querySelector(':scope > div > svg.size-10.text-red-500'))
              } };
            } catch { return point; }
          })()`
        : expression;
      let facts: Record<string, boolean | number> | undefined;
      try {
        return record(await waitRead(readExpression, phase, 30_000, value => {
          if (value && typeof value === 'object' && !Array.isArray(value)) {
            const row = value as Record<string, unknown>;
            if (row.unavailableTarget === true) {
              facts = {
                matches: Number.isSafeInteger(row.matches) && Number(row.matches) >= 0
                  ? Math.min(Number(row.matches), 256) : 0,
                disabled: row.disabled === true, ariaDisabled: row.ariaDisabled === true,
                pointerEventsNone: row.pointerEventsNone === true,
                centerInViewport: row.centerInViewport === true, hitPresent: row.hitPresent === true,
              };
              if (bootstrapRead && row.bootstrapFacts && typeof row.bootstrapFacts === 'object' &&
                  !Array.isArray(row.bootstrapFacts)) {
                const bootstrap = row.bootstrapFacts as Record<string, unknown>;
                for (const key of ['rootPresent', 'uiInitialized', 'splashPresent', 'splashPositiveSize',
                  'splashError', 'splashSlow', 'documentComplete', 'languageEnglish', 'languageEmpty',
                  'rootFallbackShape']) {
                  if (typeof bootstrap[key] === 'boolean') facts[key] = bootstrap[key];
                }
                for (const [key, limit] of [['rawMatches', 256], ['rootChildren', 16]] as const) {
                  if (Number.isSafeInteger(bootstrap[key]) && Number(bootstrap[key]) >= 0)
                    facts[key] = Math.min(Number(bootstrap[key]), limit);
                }
              }
              return false;
            }
          }
          return Boolean(value);
        }));
      } catch (error) {
        if (facts) throw new Error(`UI target read failed: ${phase}; facts=${JSON.stringify(facts)}`, { cause: error });
        throw error;
      }
    };
    let point = await readPoint(label);
    options.assertOwnedRenderer();
    step({ action: 'mouseMoved', label: 'hover ' + label, selector, target: point });
    await cdp.send('Input.dispatchMouseEvent', {
      type: 'mouseMoved',
      x: point.x,
      y: point.y,
    });
    point = await readPoint(label + ' after pointer enter');
    // Async Host hydration can shift the DOM after hover. Check the original
    // target is stable before ONE physical click, never replay an uncertain click.
    let stableSamples = 0;
    for (let sample = 0; sample < 15 && stableSamples < 2; sample++) {
      await new Promise<void>((done) => setTimeout(done, 100));
      const next = await readPoint(label + ' stable target');
      stableSamples =
        next.x === point.x && next.y === point.y && next.tag === point.tag
          ? stableSamples + 1
          : 0;
      point = next;
    }
    assert.ok(stableSamples === 2, 'Original UI target did not settle before one click');
    assert.equal(typeof point.x, 'number');
    assert.equal(typeof point.y, 'number');
    options.assertOwnedRenderer();
    const finalPoint = record(await cdp.evaluate(expression));
    assert.notEqual(finalPoint.unavailableTarget, true, 'Original UI target unavailable after ownership check');
    assert.deepEqual(
      [finalPoint.x, finalPoint.y, finalPoint.tag],
      [point.x, point.y, point.tag],
      'Original UI target moved after ownership check'
    );
    options.assertOwnedRenderer();
    step({
      action: 'mouseClick',
      label,
      selector,
      expectedText: text,
      target: point,
      state: 'attempted',
    });
    // Never repeat a click after an uncertain response.
    await cdp.send('Input.dispatchMouseEvent', {
      type: 'mousePressed',
      x: point.x,
      y: point.y,
      button: 'left',
      clickCount: 1,
    });
    await cdp.send('Input.dispatchMouseEvent', {
      type: 'mouseReleased',
      x: point.x,
      y: point.y,
      button: 'left',
      clickCount: 1,
    });
  };
  const click = (selector: string, label: string, text?: string): Promise<void> =>
    clickExpression(target(selector, text), label, selector, text);
  const hoverExpression = async (expression: string, label: string): Promise<void> => {
    let previous: { x: number; y: number } | undefined, stable = 0;
    // Canonical effects can settle before their renderer layout. Sample the
    // original eligible target within one read deadline, then move only once.
    const point = record(await waitRead(expression, label, 30_000, value => {
      const row = value && typeof value === 'object' && !Array.isArray(value)
        ? value as Record<string, unknown> : undefined;
      if (!row || row.unavailableTarget === true || typeof row.x !== 'number' ||
          typeof row.y !== 'number' || !Number.isFinite(row.x) || !Number.isFinite(row.y)) {
        previous = undefined; stable = 0;
        return false;
      }
      stable = previous?.x === row.x && previous?.y === row.y ? stable + 1 : 1;
      previous = { x: row.x, y: row.y };
      return stable >= 3;
    }));
    options.assertOwnedRenderer();
    step({ action: 'mouseMoved', label, target: point });
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: point.x, y: point.y });
  };
  const scrollTo = async (
    selector: string, label: string, text?: string, maxWheelEvents = 12,
    scrollOptions: { requireCenterHit?: boolean } = {}
  ): Promise<void> => {
    assert.ok(Number.isSafeInteger(maxWheelEvents) && maxWheelEvents >= 1 && maxWheelEvents <= 32);
    // Allow one final visibility read after the last wheel; never dispatch
    // an extra input event after reaching the TEST-only bounded budget.
    for (let attempt = 0; attempt <= maxWheelEvents; attempt++) {
      options.assertOwnedRenderer();
      const found = record(
        await waitRead(
          `(() => {
        const rows=[...document.querySelectorAll(${desktopJsLiteral(selector)})]${text === undefined ? '' : `.filter(e=>e.textContent.trim()===${desktopJsLiteral(text)})`};
        if(rows.length!==1)return null;
        const e=rows[0],r=e.getBoundingClientRect();
        let parent=e.parentElement;
        while(parent&&!(parent.scrollHeight>parent.clientHeight&&/auto|scroll/.test(getComputedStyle(parent).overflowY)))parent=parent.parentElement;
        const p=(parent??document.documentElement).getBoundingClientRect();
        const top=Math.max(0,p.top),bottom=Math.min(innerHeight,p.bottom);
        if(bottom<=top||!r.width||!r.height)return null;
        const x=Math.max(1,Math.min(innerWidth-1,p.x+p.width/2)),y=(top+bottom)/2;
        const hit=${scrollOptions.requireCenterHit === true ? 'document.elementFromPoint(r.x+r.width/2,r.y+r.height/2)' : 'e'};
        return {visible:r.top>=top&&r.bottom<=bottom&&Boolean(hit&&(hit===e||e.contains(hit))),x,y,delta:Math.max(-600,Math.min(600,r.y+r.height/2-y))};
      })()`,
          label
        )
      );
      if (found.visible === true) return;
      if (attempt === maxWheelEvents) break;
      assert.equal(typeof found.x, 'number');
      assert.equal(typeof found.y, 'number');
      assert.equal(typeof found.delta, 'number');
      step({ action: 'mouseWheel', label, selector, deltaY: found.delta });
      await cdp.send('Input.dispatchMouseEvent', {
        type: 'mouseWheel',
        x: found.x,
        y: found.y,
        deltaX: 0,
        deltaY: found.delta,
      });
      await new Promise<void>((resolve) => setTimeout(resolve, 100));
    }
    throw new Error(`UI scroll timed out: ${label}; no effect retry`);
  };
  const sidebarExpression = (subject: string): string => `(() => {
    const rows=[...document.querySelectorAll('#sidebar-tasks-panel .sidebar-task-item')];
    const found=rows.filter(e=>[...e.querySelectorAll('span')].some(s=>s.textContent.trim()===${desktopJsLiteral(subject)}));
    if(found.length!==1)return null;
    return true;
  })()`;
  // Subject span selection is exact, and the click targets its ordinary button.
  const clickSidebar = async (subject: string): Promise<void> => {
    await cdp.send('Page.bringToFront');
    // The dev renderer can expose its bridge while modules and the first Team
    // snapshot are still loading. Only this initial read gets a startup budget;
    // clicks and mutation outcomes retain their existing bounds/no-retry rule.
    await waitRead(sidebarExpression(subject), 'canonical sidebar task', 90_000);
    const expression = `(() => {
      const rows=[...document.querySelectorAll('#sidebar-tasks-panel .sidebar-task-item')];
      const found=rows.filter(e=>[...e.querySelectorAll('span')].some(s=>s.textContent.trim()===${desktopJsLiteral(subject)}));
      if(found.length!==1)return null;
      const e=found[0],r=e.getBoundingClientRect(),x=r.x+r.width/2,y=r.y+r.height/2,hit=document.elementFromPoint(x,y);
      return r.width>0&&r.height>0&&hit&&(e===hit||e.contains(hit))?{x,y}:null;
    })()`;
    const hoverPoint = record(await waitRead(expression, 'visible sidebar seed row'));
    options.assertOwnedRenderer();
    step({
      action: 'mouseMoved',
      label: 'hover sidebar row before measuring click',
      subject,
      target: hoverPoint,
    });
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseMoved', ...hoverPoint });
    // The ordinary row reveals owner/team details on pointer enter, changing its
    // height. Measure after that layout, as a human moving the mouse would do.
    // Background Electron windows throttle animation frames; use bounded reads
    // of the actual geometry instead of waiting for renderer frame callbacks.
    let point = record(await waitRead(expression, 'hovered sidebar row'));
    let stable = false;
    for (let sample = 0; sample < 10; sample++) {
      await new Promise<void>((done) => setTimeout(done, 100));
      const next = record(await waitRead(expression, 'hovered sidebar row geometry'));
      stable = point.x === next.x && point.y === next.y;
      point = next;
      if (stable) break;
    }
    assert.ok(stable, 'hovered row geometry stabilizes before the one click');
    options.assertOwnedRenderer();
    step({
      action: 'mouseClick',
      label: 'sidebar task',
      subject,
      target: point,
      state: 'attempted',
    });
    await cdp.send('Input.dispatchMouseEvent', {
      type: 'mousePressed',
      ...point,
      button: 'left',
      clickCount: 1,
    });
    await cdp.send('Input.dispatchMouseEvent', {
      type: 'mouseReleased',
      ...point,
      button: 'left',
      clickCount: 1,
    });
    step({
      observation: 'passive input delivery after sidebar click',
      value: await cdp.evaluate(
        '({focused:document.hasFocus(),visibility:document.visibilityState,events:window.__TEST_desktopInputEvents})'
      ),
    });
    await click('[role="dialog"] button', 'Open team', 'Open team');
  };
  return { observeInput, waitRead, click, clickExpression, clickSidebar, scrollTo, hoverExpression };
}

import { runDesktopTaskBoardAttachmentsUi } from './desktop-task-board-attachments-ui.ts';
import assert from 'node:assert/strict';
import { mkdir, readFile, readdir, realpath, writeFile } from 'node:fs/promises';
import { basename, join } from 'node:path';
import { performance } from 'node:perf_hooks';

import { createTeamController } from '../../packages/legacy-agent-host/dist/adapters/team/ControllerAdapter.js';
import { readDesktopTaskBoardGroupSnapshot } from './desktop-task-board-group-page-read.ts';
import { fileDigest } from './desktop-backend-fixture.ts';
import {
  desktopTaskBoardAssignmentReadyExpression,
  desktopTaskCommentInputExpression,
} from './desktop-task-comment-input-target.ts';
import { createDesktopUiControls, desktopJsLiteral } from './desktop-ui-controls.ts';
import type { UiCdpPort } from './desktop-ui-controls.ts';

const teamName = 'test-desktop-backend';
const record = (value: unknown): Record<string, unknown> => {
  assert.ok(value && typeof value === 'object' && !Array.isArray(value));
  return value as Record<string, unknown>;
};
const json = async (path: string) => record(JSON.parse(await readFile(path, 'utf8')));
const pause = () => new Promise<void>((done) => setTimeout(done, 100));

/** Existing Create, assignee, clarification and sortable card controls; offline TEST owner only. */
export async function runDesktopTaskBoardUiSmoke(
  cdp: UiCdpPort,
  options: {
    root: string;
    repo: string;
    handleId: string;
    seed: {
      taskId: string;
      subject: string;
      commandId: string;
      group?: { groupChatId: string; name: string; commandId: string };
    };
    assertOwnedRenderer(): void;
    evidence: Record<string, unknown>;
  }
): Promise<void> {
  assert.equal(await realpath(options.root), options.root);
  assert.match(basename(options.root), /^TEST-desktop-backend-/);
  const profile = await json(join(options.root, 'host-profile.json'));
  assert.equal(record(profile.owner).storageRoot, join(options.root, 'hoststore'));
  assert.equal(profile.principalId, 'TEST-human');
  assert.equal(profile.runtime, undefined, 'this flow never starts a native provider');
  const taskDirectory = join(options.root, 'hoststore/tasks', teamName);
  const teamDirectory = join(options.root, 'hoststore/teams', teamName);
  const commandDirectory = join(teamDirectory, '.host-owner/commands');
  const task = (id: string) => json(join(taskDirectory, `${id}.json`));
  const rows = async (directory: string) => {
    const names = (await readdir(directory)).filter((name) => /^[A-Za-z0-9_-]+\.json$/.test(name));
    assert.ok(names.length <= 128, 'bounded TEST product census');
    return Promise.all(names.sort().map((name) => json(join(directory, name))));
  };
  const group = options.seed.group;
  assert.ok(group, 'the two original board modes require their canonical group seed');
  const originalGroupReceipts = (await rows(commandDirectory)).filter(
    (row) => row.family === 'group-chat'
  );
  assert.equal(originalGroupReceipts.length, group ? 1 : 0);
  if (group) {
    const original = originalGroupReceipts[0]!;
    assert.equal(original.commandId, group.commandId);
    assert.equal(original.principalId, 'TEST-human');
    assert.equal(original.phase, 'completed');
    assert.equal(record(original.request).operation, 'create');
    assert.equal(record(original.request).id, group.groupChatId);
    assert.equal(record(original.response).id, group.groupChatId);
  }
  const commands = async () => {
    const all = await rows(commandDirectory);
    assert.deepEqual(
      all.filter((row) => row.family === 'group-chat'),
      originalGroupReceipts,
      'the one original fixture group receipt is retained separately and never mutated'
    );
    return all.filter((row) => row.family !== 'group-chat');
  };
  const steps: Record<string, unknown>[] = [];
  const step = (row: Record<string, unknown>) =>
    steps.push({ monotonicMs: Math.round(performance.now()), ...row });
  const proof: Record<string, unknown> = {
    status: 'INCOMPLETE',
    steps,
    scope:
      'Original Create Task dependency picker, Task assignee/Mark resolved, sortable TODO cards and blocked Start/Complete controls; offline canonical Host persistence',
    qaInventory: [
      'Create dependency through original optional fields; reciprocal canonical graph and visible blocker',
      'Original Group chat filter supplies Create Task association; exact receipt/snapshot and renderer reload retain it',
      'Change assignee through existing Radix MemberSelect; retained captured owner',
      'TEST API sets clarification because no set control exists; original Mark resolved clears it',
      'Columns/Manual controls and one trusted pointer drag change canonical column order',
      'Blocked Start refuses unresolved dependency; exact detached canonical oracle; same control succeeds after actual blocker Complete',
      'Renderer reload retains original task IDs, assignment, clarification and order without new commands',
      'Existing Task PNG and comment text file upload; canonical refs, reload/read/download and Task image removal',
    ],
    excluded: [
      'native agents/inference',
      'logs or runtime readiness',
      'nonexistent add/remove relationship UI',
      'full Stage1',
      'visual signoff before screenshot review',
    ],
    sourceSha256: await fileDigest(import.meta.filename),
  };
  options.evidence.taskBoardUiProof = proof;
  if (group)
    proof.groupAssociation = {
      status: 'INCOMPLETE',
      ...group,
      fixtureReceipt: await json(join(options.root, 'ui-group-seed-receipt.json')),
      canonicalGroupReceipt: originalGroupReceipts[0],
    };
  const ui = createDesktopUiControls(cdp, {
    assertOwnedRenderer: options.assertOwnedRenderer,
    step,
  });
  const input = (
    method: 'Input.insertText' | 'Input.dispatchMouseEvent' | 'Input.dispatchKeyEvent',
    params: Record<string, unknown>
  ) => {
    options.assertOwnedRenderer();
    return cdp.send(method, params);
  };
  const waitProduct = async <T>(
    read: () => Promise<T>,
    matches: (value: T) => boolean,
    label: string
  ): Promise<T> => {
    const deadline = Date.now() + 20_000;
    while (Date.now() < deadline) {
      options.assertOwnedRenderer();
      const value = await read();
      if (matches(value)) return value;
      await pause();
    }
    throw new Error(`Task board product read timed out: ${label}; no mutation retry`);
  };
  const screenshot = async (name: string) => {
    options.assertOwnedRenderer();
    const capture = record(
      await cdp.send('Page.captureScreenshot', { format: 'png', fromSurface: true })
    );
    assert.equal(typeof capture.data, 'string');
    const path = join(options.root, name);
    await writeFile(path, Buffer.from(String(capture.data), 'base64'), { mode: 0o600, flag: 'wx' });
    return { path, sha256: await fileDigest(path) };
  };
  // Expressions below only inspect current DOM. Input events remain the only UI actions.
  const measuredClick = async (expression: string, label: string, moveBeforePress = false) => {
    let point = record(await ui.waitRead(expression, label));
    if (point.dismissed === true) return false;
    if (moveBeforePress) {
      step({ action: 'mouseMoved', label, target: point });
      await input('Input.dispatchMouseEvent', {
        type: 'mouseMoved',
        x: point.x,
        y: point.y,
      });
      point = record(await ui.waitRead(expression, label + ' current target after pointer move'));
      if (point.dismissed === true) return false;
    }
    assert.equal(typeof point.x, 'number');
    assert.equal(typeof point.y, 'number');
    options.assertOwnedRenderer();
    step({ action: 'mouseClick', label, target: point, state: 'attempted' });
    await input('Input.dispatchMouseEvent', {
      type: 'mousePressed',
      x: point.x,
      y: point.y,
      button: 'left',
      clickCount: 1,
    });
    await input('Input.dispatchMouseEvent', {
      type: 'mouseReleased',
      x: point.x,
      y: point.y,
      button: 'left',
      clickCount: 1,
    });
    return true;
  };
  const selectOriginalAssignee = async (triggerExpression: string, optionExpression: string) => {
    for (let attempt = 1; attempt <= 2; attempt++) {
      await measuredClick(triggerExpression, 'open original assignee picker ' + attempt, true);
      if (
        await measuredClick(optionExpression, 'assign alice through original member option', true)
      )
        return;
      step({
        observation: 'owned assignee popup dismissed before any option press',
        attempt,
        navigation:
          attempt === 1 ? 'one known nonmutating reopen permitted' : 'stop before assignment',
      });
    }
    throw new Error(
      'Owned assignee popup dismissed twice before any option press; no assignment replay'
    );
  };
  const pointOf = (body: string) =>
    `(() => { const e=(()=>{${body}})();if(e?.dismissed===true)return e;if(!e)return null;const r=e.getBoundingClientRect(),x=r.x+r.width/2,y=r.y+r.height/2,hit=document.elementFromPoint(x,y);return r.width>0&&r.height>0&&hit&&(e===hit||e.contains(hit))&&!e.disabled?{x,y}:null; })()`;
  const card = (id: string) => `.kanban-task-card[data-task-id="${id}"]`;
  const receiptFor = async (
    operation: string,
    taskId: string,
    predicate: (payload: Record<string, unknown>) => boolean = () => true
  ) => {
    const found = await waitProduct(
      commands,
      (all) =>
        all.some((row) => {
          const command = record(row.command),
            payload = record(command.payload);
          return (
            ['completed', 'rejected'].includes(String(row.phase)) &&
            row.principalId === 'TEST-human' &&
            command.operation === operation &&
            payload.taskId === taskId &&
            predicate(payload)
          );
        }),
      operation
    );
    const matches = found.filter((row) => {
      const command = record(row.command),
        payload = record(command.payload);
      return (
        ['completed', 'rejected'].includes(String(row.phase)) &&
        row.principalId === 'TEST-human' &&
        command.operation === operation &&
        payload.taskId === taskId &&
        predicate(payload)
      );
    });
    assert.equal(matches.length, 1, 'exactly one business intent per actual control');
    return matches[0]!;
  };
  const readGroupSnapshot = (phase: string, taskIds: string[]) => {
    assert.ok(group);
    return readDesktopTaskBoardGroupSnapshot(cdp, {
      handleId: options.handleId, teamName, groupChatId: group.groupChatId,
      phase, taskIds, assertOwnedRenderer: options.assertOwnedRenderer,
    });
  };
  const selectGroupFilter = async (name: string) => {
    await ui.click('button[aria-label="Filter tasks"]', 'open original Task filters');
    await ui.click(
      'button[role="combobox"][aria-label="Group chat"]',
      'open original Group chat filter'
    );
    await ui.click('[role="option"]', 'choose original Group chat filter option', name);
    await ui.waitRead(
      `document.querySelector('button[role="combobox"][aria-label="Group chat"]')?.textContent.trim()===${desktopJsLiteral(name)}`,
      'original Group chat filter value'
    );
    await ui.click('button[aria-label="Filter tasks"]', 'close original Task filters');
    await ui.waitRead(
      `!document.querySelector('button[role="combobox"][aria-label="Group chat"]')`,
      'original Task filters closed'
    );
  };
  const before = await rows(taskDirectory);
  assert.equal(before.length, 1);
  assert.equal(before[0]!.id, options.seed.taskId);
  await ui.observeInput();
  await ui.clickSidebar(options.seed.subject);
  await ui.waitRead(
    `Boolean(document.querySelector(${desktopJsLiteral(card(options.seed.taskId))}))`,
    'canonical seed card'
  );
  proof.initialScreenshot = await screenshot('ui-task-board-initial.png');
  if (group) {
    assert.equal(before[0]!.groupChatId, group.groupChatId);
    const association = record(proof.groupAssociation);
    const seeded = await json(join(options.root, 'ui-seed-receipt.json'));
    assert.equal(record(record(seeded.command).payload).groupChatId, group.groupChatId);
    association.beforeCreate = await readGroupSnapshot('before', [options.seed.taskId]);
    await selectGroupFilter(group.name + ' (1)');
    association.originalFilterSelection = group.name;
  }

  await ui.click('button', 'open existing Create Task dialog', 'Task');
  await ui.click('[role="dialog"] #task-subject', 'focus ordinary Subject');
  const subject = 'TEST ordinary dependent board task';
  await input('Input.insertText', { text: subject });
  await ui.click(
    '[role="dialog"] button',
    'show existing optional dependency fields',
    'Show optional fields'
  );
  const blockerButton = `(() => {
    const label=[...document.querySelectorAll('[role="dialog"] label')].find(e=>e.textContent.trim()==='Blocked by tasks (optional)');
    const buttons=label?[...label.parentElement.querySelectorAll('button')].filter(e=>[...e.querySelectorAll('span')].some(s=>s.textContent.trim()===${desktopJsLiteral(options.seed.subject)})):[];
    return buttons.length===1?buttons[0]:null;
  })()`;
  // Wheel input reveals optional fields without scrollIntoView or synthetic app events.
  for (let attempt = 0; attempt < 8; attempt++) {
    if (await cdp.evaluate(pointOf(`return ${blockerButton};`))) break;
    const dialog = record(
      await ui.waitRead(
        pointOf('return document.querySelector(\'[role="dialog"]\');'),
        'visible original Task dialog'
      )
    );
    await input('Input.dispatchMouseEvent', {
      type: 'mouseWheel',
      x: dialog.x,
      y: dialog.y,
      deltaX: 0,
      deltaY: 350,
    });
    await pause();
  }
  await measuredClick(
    pointOf(`return ${blockerButton};`),
    'choose original Blocked by task option once'
  );
  await ui.scrollTo('[role="dialog"] button', 'original Create Task control', 'Create');
  await ui.click('[role="dialog"] button', 'submit original dependent Task once', 'Create');
  await ui.waitRead(
    `!document.querySelector('[role="dialog"] #task-subject')`,
    'Create Task closes'
  );
  const afterCreate = await waitProduct(
    () => rows(taskDirectory),
    (all) => all.length === 2,
    'one UI-created task'
  );
  const created = afterCreate.filter((row) => row.subject === subject);
  assert.equal(created.length, 1);
  const taskId = String(created[0]!.id);
  assert.match(taskId, /^[a-f0-9-]{36}$/);
  assert.equal(created[0]!.status, 'pending');
  assert.deepEqual(created[0]!.blockedBy, [options.seed.taskId]);
  assert.deepEqual((await task(options.seed.taskId)).blocks, [taskId]);
  const creates = await waitProduct(
    async () =>
      (await commands()).filter(
        (row) =>
          record(row.command).operation === 'task.create' &&
          record(record(row.command).payload).subject === subject
      ),
    (matches) => matches.length === 1 && matches[0]!.phase === 'completed',
    'one original UI-created Task receipt completed'
  );
  assert.equal(creates.length, 1);
  assert.equal(creates[0]!.phase, 'completed');
  assert.equal(creates[0]!.principalId, 'TEST-human');
  assert.equal(record(creates[0]!.effects).taskId, taskId);
  proof.createReceipt = creates[0];
  if (group) {
    assert.equal(created[0]!.groupChatId, group.groupChatId);
    assert.equal(record(record(creates[0]!.command).payload).groupChatId, group.groupChatId);
    record(proof.groupAssociation).afterCreate = await readGroupSnapshot('created', [
      options.seed.taskId,
      taskId,
    ]);
    await selectGroupFilter('All groups');
    record(proof.groupAssociation).filterClearedBeforeRemainingWorkflow = true;
  }

  // No current UI sets clarification. This is explicit TEST setup, never a signoff action.
  options.assertOwnedRenderer();
  const setupCommandId = 'TEST-task-board-clarification-setup';
  const setup = record(
    await cdp.evaluate(
      `window.electronAPI.agentBackend.invoke(${desktopJsLiteral({ handle: { handleId: options.handleId }, commandId: setupCommandId, operation: 'task.clarification', payload: { taskId, value: 'user' } })})`
    )
  );
  assert.equal(setup.ok, true);
  assert.equal(record(setup.value).phase, 'completed');
  step({
    fixtureAction: 'captured TEST owner clarification setup',
    commandId: setupCommandId,
    taskId,
  });
  // The owner ACK precedes the board refresh, which can reorder the two cards.
  // Observe the original card's new badge before measuring its one detail click.
  await ui.waitRead(`(() => {
    const node=document.querySelector(${desktopJsLiteral(card(taskId))});
    return node&&[...node.querySelectorAll('span')].some(span=>span.textContent.trim()==='Awaiting user');
  })()`, 'original Task card has rendered the completed clarification setup');
  await ui.scrollTo(`${card(taskId)} h5`, 'original clarified Task title in its refreshed position');
  await ui.click(`${card(taskId)} h5`, 'open original Task detail');
  await ui.waitRead(
    `document.querySelector('[role="dialog"]')?.textContent.includes('Awaiting clarification from you')`,
    'existing clarification banner'
  );
  const assignmentOwner = record(
    await ui.waitRead(
      desktopTaskCommentInputExpression(options.handleId, taskId),
      'capture the original Task detail owner before assignment'
    )
  );
  const { contextId } = record(assignmentOwner.identity);
  const { surfaceId } = assignmentOwner;
  assert.ok(typeof contextId === 'string' && typeof surfaceId === 'string');
  const assigneeDialog = `
    const dialogs=[...document.querySelectorAll('[role="dialog"]')].filter(d=>d.getClientRects().length&&d.querySelector('button[role="combobox"]'));
    if(dialogs.length!==1||!dialogs[0].textContent.includes(${desktopJsLiteral('#' + String(created[0]!.displayId))})||
      ![...dialogs[0].querySelectorAll('button')].some(e=>e.textContent.trim()===${desktopJsLiteral(subject)}))return null;
    const triggers=dialogs[0].querySelectorAll('button[role="combobox"]');if(triggers.length!==1||triggers[0].disabled)return null;
    const trigger=triggers[0];`;
  await selectOriginalAssignee(
    pointOf(
      assigneeDialog +
        `if(trigger.getAttribute('aria-expanded')!=='false')return null;return trigger;`
    ),
    pointOf(
      assigneeDialog +
        `
    if(trigger.getAttribute('aria-expanded')==='false')return {dismissed:true};
    const focused=document.activeElement;
    const list=focused?.matches('[cmdk-input]')?document.getElementById(focused.getAttribute('aria-controls')):null;
    const popup=list?.closest('[role="dialog"][data-state="open"]');
    const popups=[...document.querySelectorAll('[role="dialog"][data-state="open"]')].filter(e=>e.getClientRects().length&&e.querySelector('[cmdk-input]'));
    if(!list?.matches('[cmdk-list]')||!popup||popups.length!==1||popups[0]!==popup||!popup.contains(focused)||
      popup.getAnimations().some(a=>a.playState==='running'))return null;
    const options=[...list.querySelectorAll('[cmdk-item][data-value="alice"]')].filter(e=>e.getClientRects().length&&e.getAttribute('aria-disabled')!=='true');
    return options.length===1?options[0]:null;
  `
    )
  );
  await waitProduct(
    () => task(taskId),
    (row) => row.owner === 'alice',
    'canonical Task assignment'
  );
  proof.assignmentReceipt = await receiptFor(
    'task.assign',
    taskId,
    (payload) => payload.owner === 'alice'
  );
  proof.assignmentUiReady = await ui.waitRead(
    desktopTaskBoardAssignmentReadyExpression(options.handleId, taskId, {
      contextId,
      surfaceId,
    }),
    'original assignment refresh and accepted Task owner settle before Mark resolved'
  );
  await ui.waitRead(
    `[...document.querySelectorAll('[role="dialog"] button')].some(e => e.textContent.trim() === ${desktopJsLiteral('#' + String(before[0]!.displayId))})`,
    'original dependency reference visible'
  );
  proof.dependencyScreenshot = await screenshot('ui-task-board-assigned-blocked.png');
  // Re-read the original owner and enabled hit-tested control at each shared
  // settling sample before one physical press. No effect retry.
  await ui.clickExpression(
    `(async()=>{
      const owner=await ${desktopTaskBoardAssignmentReadyExpression(options.handleId, taskId, { contextId, surfaceId }, 'clarification')};
      if(!owner)return null;
      return ${pointOf(`
        const dialog=document.getElementById(owner.inputId)?.closest('[role="dialog"]');
        const buttons=[...dialog?.querySelectorAll('button')??[]].filter(e=>e.textContent.trim()==='Mark resolved');
        return buttons.length===1?buttons[0]:null;
      `)};
    })()`,
    'clear original clarification once'
  );
  await ui.waitRead(
    `!document.querySelector('[role="dialog"]')?.textContent.includes('Awaiting clarification from you')`,
    'clarification banner cleared'
  );
  assert.equal((await task(taskId)).needsClarification, undefined);
  proof.clarificationReceipt = await receiptFor(
    'task.clarification',
    taskId,
    (payload) => payload.value === null
  );
  await ui.click('[role="dialog"] button', 'close original Task detail', 'Close');
  await ui.waitRead(`!document.querySelector('[role="dialog"]')`, 'Task detail closed');

  await ui.click('button[aria-label="Columns view"]', 'switch existing board to Columns');
  await ui.click('button[aria-label="Sort tasks"]', 'open existing sort controls');
  await measuredClick(
    pointOf(
      `return [...document.querySelectorAll('button')].find(e=>e.querySelector('.font-medium')?.textContent.trim()==='Manual');`
    ),
    'choose original Manual sorting'
  );
  // Manual sorting enables DndContext and remounts the board with its popover closed.
  await ui.waitRead(`!document.querySelector('[role="dialog"]')`, 'original sort popover closed');
  const orderBefore = await ui.waitRead(
    `(() => {const cards=[...document.querySelectorAll('.kanban-task-card[data-task-id]')];if(cards.length!==2||cards.some(e=>!e.parentElement.hasAttribute('aria-roledescription')))return null;return cards.map(e=>e.dataset.taskId);})()`,
    'two original sortable cards'
  );
  assert.ok(Array.isArray(orderBefore) && orderBefore.length === 2);
  const dragged = String(orderBefore[1]),
    target = String(orderBefore[0]);
  await ui.scrollTo(card(dragged), 'reveal original sortable source');
  const geometry = record(
    await ui.waitRead(
      `(() => {
    const a=document.querySelector(${desktopJsLiteral(card(dragged))}),b=document.querySelector(${desktopJsLiteral(card(target))});if(!a||!b)return null;
    const p=a.getBoundingClientRect(),q=b.getBoundingClientRect();
    if(!p.width||!q.width||p.top<0||q.top<0||p.bottom>innerHeight||q.bottom>innerHeight)return null;
    const point={x:p.x+Math.min(100,p.width/2),y:p.y+20,toX:q.x+Math.min(100,q.width/2),toY:q.y+20};
    if(!a.contains(document.elementFromPoint(point.x,point.y))||!b.contains(document.elementFromPoint(point.toX,point.toY)))return null;
    return point;
  })()`,
      'visible sortable source and destination'
    )
  );
  for (const key of ['x', 'y', 'toX', 'toY']) assert.equal(typeof geometry[key], 'number');
  const x = Number(geometry.x),
    y = Number(geometry.y),
    toX = Number(geometry.toX),
    toY = Number(geometry.toY);
  step({ action: 'pointerDrag', state: 'attempted', dragged, target, geometry });
  options.assertOwnedRenderer();
  await input('Input.dispatchMouseEvent', { type: 'mouseMoved', x, y });
  await input('Input.dispatchMouseEvent', {
    type: 'mousePressed',
    x,
    y,
    button: 'left',
    buttons: 1,
    clickCount: 1,
  });
  let releaseX = x,
    releaseY = y;
